DETAIL={
"blockosaurus":dict(shots=6,video=True,about=["Blockosaurus is a free, offline block puzzle game with dinosaurs. Drag wood and colour blocks onto the board, clear rows and columns, and collect 12 real dinosaurs along the way.","There is no WiFi requirement and no time limit, so you can play on the bus, at home or anywhere you have a few quiet minutes.","Journey mode takes you through hundreds of stages with boss levels and 3-star goals. Classic is relaxed endless play, Daily Challenge gives everyone the same new puzzle each day, and Sudoku Mode adds 4x4 square clears.","Hatch dino eggs for gems, coins or new dinosaurs, then level your dinos up. Each one grants a power in play: Smash, Reroll, Rewind, Wave or Last Stand."],how=["Drag blocks onto the 8x8 board.","Fill a full row or column to clear it.","Clear several lines at once for combos and streak bonuses.","Plan ahead, because the game ends when no block fits."],feats=[("12 collectible dinos","T-Rex, Triceratops, Stegosaurus, Spinosaurus and more, each with its own power."),("Five game modes","Journey, Classic, Daily Challenge, Sudoku Mode and Monthly Challenge."),("Fully offline","No internet needed, play anywhere."),("Themes and skins","Royal blue and gold or warm wood boards, plus piece skins and backdrops."),("Leaderboard","Compare your score with other players."),("Relaxing feel","Smooth animations and calm music.")]),
"bubbleshooter":dict(shots=6,video=True,about=["Aim, shoot and pop your way through more than 1,000 handcrafted bubble levels in Bubble Shooter: Rainbow Pop.","Line up three or more bubbles of the same colour and watch them burst. Cut a cluster loose from the ceiling and the whole thing drops for bonus points.","Journey across colourful worlds with real bank shots off the walls, boosters, daily rewards and live events.","Quick sessions, smooth physics and bright visuals make it easy to pick up and hard to put down."],how=["Drag to aim, release to shoot.","Match three or more bubbles of the same colour to pop them.","Drop whole clusters by cutting them from the ceiling.","Use boosters on tricky boards and clear the level for stars."],feats=[("1,000+ levels","Handcrafted boards with growing challenge."),("Many worlds","From sunny meadows to ocean and beyond."),("Boosters","Bombs, colour blasts and more for tough spots."),("Daily rewards","Come back each day for coins and surprises."),("Live events","Limited-time events with special prizes."),("Play anywhere","Short, satisfying sessions on the go.")]),
"crease":dict(shots=6,video=False,about=["CREASE is a fast, offline cricket scorer built for real matches, plus a team hub to organise your squad around them.","Score any format, T20, T10, ODI or custom overs, with a one-handed keypad for runs, wides, no-balls, byes and wickets. Undo any ball, and the app handles strike rotation, overs, free hits and the result.","Every match gets a full scorecard with batting, bowling, run-rate charts and a wagon wheel. Share a match card image or export the scorecard as a PDF.","Build your team, track leaderboards and earn XP and badges as you score more matches."],how=["Create a match and pick the format and overs.","Tap each ball on the scoring keypad.","Watch the live scorecard and wagon wheel update.","Share the result card or PDF when the game ends."],feats=[("Ball-by-ball scoring","Fast keypad with undo and automatic extras."),("Full scorecards","Batting, bowling, charts and wagon wheel."),("Works offline","Score matches with no signal."),("Team hub","Squads, logos and share codes."),("Leaderboards","Most runs, sixes, wickets and best economy."),("XP and badges","Climb from Rookie to Legend.")]),
"chorequestkids":dict(shots=6,video=False,about=["Chore Quest Kids is a family chore chart and rewards app that turns daily jobs into a game. Kids finish chores, routines and a short daily lesson to earn coins and stars, then trade them for rewards the family chooses.","Parents set up chores, rewards and two PINs: one for parents and one for kids. Kids send photo proof, parents approve, and coins arrive instantly.","Morning and bedtime routines come with visual step-by-step timers and a stars-and-reward goal. A short daily lesson or story adds learning time.","An optional family account lets the whole household share one view of progress."],how=["Parents add chores and rewards, and set two PINs.","Kids see their chore list and complete tasks.","Kids send a photo as proof.","Parents approve and coins are added for the reward store."],feats=[("Chore chart","23 ready-made chores and 40 quick ideas."),("Routines","Morning and bedtime step-by-step timers."),("Rewards store","Families choose rewards like movie night."),("Daily lesson","A short family-friendly video and question."),("Pocket money","Show coin values in your own currency."),("Parent approval","Parents stay in control.")]),
"mahjong":dict(shots=7,video=False,about=["Mahjong Solitaire: Tile Match is the classic tile-matching puzzle, reimagined with a calm garden setting and five real mahjong board layouts.","Clear the board one matching pair at a time. The difficulty ramps up gently, easing new players in instead of dropping them on the hardest board.","Play 1,000 levels across 5 phases, from a wide-open warm-up board to the full 144-tile Turtle layout, and collect 16 tile themes along the way.","Everything works offline, with free daily coins and a daily challenge to keep things fresh."],how=["Find two identical free tiles.","Tap both to remove them.","Clear every tile to finish the level.","Use Hint, Shuffle or Undo if you get stuck."],feats=[("1,000 levels","Five phases with a gentle difficulty curve."),("5 layouts","Turtle, Pyramid, Bridge, Butterfly and Gateway."),("16 tile themes","Unlock and collect new looks."),("Daily challenge","Streaks and milestone coin bonuses."),("Hint, Shuffle, Undo","Help when you get stuck."),("Offline play","No internet needed.")]),
"pakistanopoly":dict(shots=6,video=True,about=["Pakistanopoly is a fun, fast desi board game, a Pakistani twist on the classic Monopoly-style property game.","Roll the dice, tour the country, buy up cities, collect rent and bankrupt your rivals to become the ultimate tycoon.","The 40-tile board features 22 Pakistani cities, railway stations and utilities, with Qismat and Sandooq cards full of local flavour.","Choose from tokens like the Rickshaw, Truck, Cricket Bat, Chai Cup, Markhor and Crescent."],how=["Roll the dice and move around the board.","Buy cities and collect them in colour groups.","Build up your properties and collect rent.","Bankrupt your rivals to win."],feats=[("22 Pakistani cities","From Gwadar and Sukkur to Lahore, Karachi and Islamabad."),("Desi flavour","Qismat and Sandooq cards with local humour."),("Fun tokens","Rickshaw, Truck, Cricket Bat, Chai Cup and more."),("Neon style","A bold dark look with glowing accents."),("Houses and hotels","Build up your properties."),("Quick games","Easy to start, fun to master.")]),
"strideup":dict(shots=6,video=False,about=["StrideUp is a step tracker and fitness companion that turns walking into daily progress.","See today's steps at a glance, follow your progress over time and earn awards as you hit goals.","Follow guided workouts and a simple plan, level up as you go, and keep your profile and streaks in one place.","Groups and friendly challenges help you stay motivated."],how=["Open the app and start walking.","Check your steps on the Today screen.","Follow a plan or workout to mix things up.","Earn awards and level up as you improve."],feats=[("Step tracking","Daily steps and progress at a glance."),("Workouts","Guided exercises for variety."),("Plans","A simple structure to follow."),("Awards and levels","Celebrate every milestone."),("Groups","Stay motivated with friends."),("Your profile","Track your history.")]),
"testershub":dict(shots=6,video=True,about=["TestersHub helps indie developers find app testers, complete closed testing on Google Play and track their 14-day test in one place.","Submit your app with its closed-test opt-in link, choose what testers should focus on, and add a safety buffer of extra testers.","Test other developers' apps to earn Hub Credits, then spend them to get testers for your own app. Credits never reward ratings or reviews, only real testing.","Follow your test with a progress ring, day-by-day timeline, tester roster and daily check-ins."],how=["Submit your app with its closed-test link.","Test other developers' apps and check in daily.","Earn Hub Credits for completed tests.","Spend credits to get testers and track your 14 days."],feats=[("Find testers","Reach developers who test in return."),("Earn Hub Credits","Complete tests to earn credits."),("14-day tracking","Progress ring, timeline and roster."),("Daily check-ins","Keep testers engaged."),("Structured feedback","Bug, crash and UI reports with device info."),("Safety buffer","Stay above the required tester count.")])}
